import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0011 — The morphism engine (hierarchical block-level optimization)","description":"","frontmatter":{"title":"Plan 0011 — The morphism engine (hierarchical block-level optimization)","type":"plan","date":"2026-10-14T00:00:00.000Z","status_note":"draft — queued after 0010 lands."},"headers":[],"relativePath":"graphopt/project/plans/0011-morphism-engine.md","filePath":"vendored/graphopt/project/plans/0011-morphism-engine.md"}`),a={name:`graphopt/project/plans/0011-morphism-engine.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0011-—-the-morphism-engine-hierarchical-block-level-optimization" tabindex="-1">Plan 0011 — The morphism engine (hierarchical block-level optimization) <a class="header-anchor" href="#plan-0011-—-the-morphism-engine-hierarchical-block-level-optimization" aria-label="Permalink to “Plan 0011 — The morphism engine (hierarchical block-level optimization)”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Whole-model optimization is bounded by tensor-level eqsat — exponential on real stacks. The generalization of the carrier idea one level up: <strong>lift each block to a morphism signature and optimize the morphism-level graph</strong> — a tiny object (N blocks, not N×ops enodes) where composition is polynomial algebra, not saturation.</p><p>search : model → block signatures → morphism-graph laws → chosen composition lower : reify the chosen composition to concrete terms → lower per-block as today → certify per law</p><h2 id="the-compression" tabindex="-1">The compression <a class="header-anchor" href="#the-compression" aria-label="Permalink to “The compression”">​</a></h2><ul><li><code>optimize_compositional</code> caps at adjacent pairs; whole-model eqsat hits the enode cliff at ~8 blocks (the measured cost cliff).</li><li>At the morphism level a 48-layer model is a 48-node graph with ~5 law families — search is rewriting, not saturation.</li></ul><h2 id="stage-0-—-block-signatures-the-algebra" tabindex="-1">Stage 0 — Block signatures (the algebra) <a class="header-anchor" href="#stage-0-—-block-signatures-the-algebra" aria-label="Permalink to “Stage 0 — Block signatures (the algebra)”">​</a></h2><p><code>BlockSig = (in_projs: [Param], out_proj: Param|None, norm: {kind,dims}, act, residual: bool, shape)</code> extracted from the module DAG via the Composer port. Prove the algebra on 2-block fixtures: <code>A.out ∘ B.in</code> composition through norms (diagonal absorption), residual <code>+</code> monoid laws, <code>embed ∘ head</code> tying.</p><h2 id="stage-1-—-the-morphism-engine" tabindex="-1">Stage 1 — The morphism engine <a class="header-anchor" href="#stage-1-—-the-morphism-engine" aria-label="Permalink to “Stage 1 — The morphism engine”">​</a></h2><p>The lifted graph (blocks as objects, wires as arrows) + laws that operate <em>on signatures</em> — never touching tensor-level terms until reify. Each law carries its certificate recipe so reified programs remain verified.</p><h2 id="stage-2-—-headline-transforms-ranked" tabindex="-1">Stage 2 — Headline transforms (ranked) <a class="header-anchor" href="#stage-2-—-headline-transforms-ranked" aria-label="Permalink to “Stage 2 — Headline transforms (ranked)”">​</a></h2><ol><li><strong>Cross-layer KV latent sharing</strong> (MLA-style) — fold K/V projections across layers into a shared low-rank latent. Decode KV traffic drops ~head-count factor.</li><li><strong>Residual-stream reassociation</strong> — global <code>+</code> monoid over N blocks; batch projections globally.</li><li><strong>Norm-fusion cascades</strong> — norm diagonals flow through block chains into the next weights.</li><li><strong>Inter-block out∘in windows</strong> — extend cross-pairs to windows ≥3.</li><li><strong>TP-shard planning</strong> — fused-vs-split pairing at model scale.</li></ol><h2 id="stage-3-—-where-it-pays" tabindex="-1">Stage 3 — Where it pays <a class="header-anchor" href="#stage-3-—-where-it-pays" aria-label="Permalink to “Stage 3 — Where it pays”">​</a></h2><p>Decode-bound LLM serving (bandwidth regime), long-context attention, MoE at scale. Vision/conv stacks remain parity until conv signatures land.</p><h2 id="stage-4-—-bar" tabindex="-1">Stage 4 — Bar <a class="header-anchor" href="#stage-4-—-bar" aria-label="Permalink to “Stage 4 — Bar”">​</a></h2><p>Honest target: <strong>&gt;1.2× E2E on a real-scale model</strong> from morphism transforms alone, with certificates. Below that, document why.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><ul><li>0006 <code>search</code>/<code>lower</code> seam (done)</li><li>0007 <code>Composer</code> port (done — the abstraction boundary already exists)</li><li>0009 <code>RuleSet</code> (done — morphism laws become a preset)</li><li>0010 perf stages (in flight — not required; morphism search is already polynomial)</li></ul><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to “Risks”">​</a></h2><ul><li>Signature coverage: only structurally-recognized blocks lift (opaque = boundary, same as carriers) — honest partial coverage.</li><li>Laws that <em>look</em> composable can fail numerics verification when reified — verify fp64 at each level, not just the signature level.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};